// What the retention prune would delete from the `conversation-logs` branch, as a
// pure function of the branch's file listing — no git, no clock of its own.
// worker.mjs is the I/O shell around this.
//
// TWO conditions, never one. A capture is deletable when it is BOTH past
// `retention_days` AND marked processed by an extract run. Age alone is what this
// task must never act on: the extract run is the only thing that ever reads a log,
// so pruning on the calendar would delete conversations nobody mined. Age is
// arithmetic this task owns; consumption is a fact only the extract run knows, and
// it says so by writing the marker.
//
// THE MARKER IS A SIDECAR FILE, `<log>.processed` beside the log it is about.
// The alternatives were a `processed/` prefix and a manifest: the prefix moves the
// captures into a subdirectory, where the two existing readers of this branch (the
// `conversationLogs` signal collector and the usage fold, both of which list the
// tree non-recursively and match the capture filename) stop seeing them and start
// under-reporting; a manifest is one file every extract run rewrites, which is the
// one shape an agent can clobber. A sidecar is additive, flat, one write per log,
// and invisible to both existing parsers — their patterns anchor on `.jsonl`.

import { parseLogFilename } from '../../capture-log.mjs';

// The parse comes from the pack's own capture step — its sibling two directories
// up, always vendored with this task — rather than a fourth copy of the filename
// format guarded against drift.

export const MARKER_SUFFIX = '.processed';
export const markerFor = (log) => `${log}${MARKER_SUFFIX}`;

export const ageDays = (capturedAt, now) => (Date.parse(now) - Date.parse(capturedAt)) / 86400000;

// Plan one prune over `names` (the branch's flat file listing) at `now`.
//
//   delete  — paths to remove: each deletable capture with its marker, plus any
//             marker whose capture is already gone (otherwise it outlives what it
//             was about, and nothing else would ever remove it).
//   holding — captures past retention that carry NO marker: the count this task
//             is deliberately not acting on. Reported rather than silent, because
//             a repo whose extract stopped running looks identical to a quiet one
//             from inside this worker.
//
// A retention that is not a positive number means the prune is off for this repo
// (unset = capture-only adoption, the fail-safe default) — nothing is deletable.
export function planPrune({ names, retentionDays, now }) {
  const present = new Set(names);
  const logs = names
    .map((name) => ({ name, parsed: parseLogFilename(name) }))
    .filter((f) => f.parsed !== null);

  const off = !(typeof retentionDays === 'number' && retentionDays > 0);
  const aged = off ? [] : logs.filter((f) => ageDays(f.parsed.capturedAt, now) > retentionDays);

  const del = [];
  const holding = [];
  for (const f of aged) {
    if (present.has(markerFor(f.name))) del.push(f.name, markerFor(f.name));
    else holding.push(f.name);
  }

  // An orphan marker: its capture was pruned (or never existed). Independent of
  // retention — the marker carries no stamp of its own to age, and there is
  // nothing left for it to mark.
  const orphans = names.filter((n) => n.endsWith(MARKER_SUFFIX)
    && !present.has(n.slice(0, -MARKER_SUFFIX.length))
    && parseLogFilename(n.slice(0, -MARKER_SUFFIX.length)) !== null);

  return { delete: [...del, ...orphans], holding, logCount: logs.length, off };
}
EOF

cat > packs/grow_with_claudinite/tasks/logs-prune/worker.mjs <<'EOF'
// The logs-prune preprocessing entry point — the script the scheduler runs as
// `node worker.mjs` (cwd = this task dir, bounded by prework_timeout). The whole
// task: no agent, no dispatch issue.
//
// It holds no decision logic: what is deletable is `prune-logs.mjs`, its sibling in
// this task folder, which is a pure function of the branch listing and the clock.
// This file is the I/O shell:
//
//   1. read `retention_days` off this repo's own declaration (unset = the prune is
//      off — capture-only adoption, and the fail-safe default);
//   2. fetch the orphan `conversation-logs` branch and list it (plain local git —
//      the branch is in this repo, so one tree read beats any REST round-trip);
//   3. plan, and commit the removals onto the branch tip.
//
// THE CHECKOUT IS NEVER TOUCHED. The scheduler runs every due task in one checkout,
// so this builds its tree through plumbing against a throwaway index and pushes the
// commit straight from the object store: HEAD, the index and the working tree are
// where the next task left them, and a run that dies leaves nothing to clean up.
//
// AND THE BRANCH'S HISTORY IS NEVER REWRITTEN. The push is a fast-forward on the
// branch's own tip — plain remove commits, exactly what the capture step's add
// commits are. A capture landing between the fetch and the push loses the race
// benignly: the push is rejected, and the retry re-plans against the new tip.

import { execFileSync } from 'node:child_process';
import { readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { DEFAULT_BRANCH } from '../../capture-log.mjs';
import { planPrune } from './prune-logs.mjs';

const PUSH_ATTEMPTS = 3;

const slotId = process.env.CLAUDINITE_SLOT_ID || '';
const log = (s) => console.log(`logs-prune${slotId ? ` [${slotId}]` : ''}: ${s}`);

const git = (root, args, opts = {}) => execFileSync('git', ['-C', root, ...args], {
  encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts,
});

// This repo's declared retention, or null when the pack is declared without it.
// Anything unparsable is "unset" — the prune's one failure direction is deleting
// what it should not, so an unreadable declaration must not become a number.
export function readRetentionDays(root) {
  let config;
  try { config = JSON.parse(readFileSync(join(root, '.claudinite-checks.json'), 'utf8')); } catch { return null; }
  const entry = (config?.packs ?? []).find((p) => (typeof p === 'string' ? p : p?.id) === 'grow_with_claudinite');
  const days = typeof entry === 'object' ? entry?.config?.retention_days : undefined;
  return typeof days === 'number' && days > 0 ? days : null;
}

// Commit the removals onto `tip` and push. Plumbing only — see the header.
function pushRemovals(root, { remote, tip, paths, message }) {
  const index = join(tmpdir(), `claudinite-prune-${process.pid}-${Date.now()}.index`);
  const plumb = (args) => git(root, args, { env: { ...process.env, GIT_INDEX_FILE: index } });
  try {
    plumb(['read-tree', tip]);
    for (const path of paths) plumb(['update-index', '--force-remove', path]);
    const tree = plumb(['write-tree']).trim();
    const commit = git(root, [
      '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
      'commit-tree', tree, '-p', tip, '-m', message,
    ]).trim();
    git(root, ['push', '--quiet', remote, `${commit}:refs/heads/${DEFAULT_BRANCH}`]);
    return commit;
  } finally { rmSync(index, { force: true }); }
}

export async function main() {
  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
  const token = process.env.GITHUB_TOKEN;
  if (!repo) throw new Error('CLAUDINITE_REPO / GITHUB_REPOSITORY is not set (owner/repo)');
  if (!token) throw new Error('GITHUB_TOKEN is not set — the prune cannot read or write the logs branch');
  const remote = `https://x-access-token:${token}@github.com/${repo}.git`;

  const retentionDays = readRetentionDays(root);
  if (retentionDays === null) {
    log('retention_days is unset for this repo — capture-only adoption, deleting nothing');
    return;
  }
  if (!git(root, ['ls-remote', '--heads', remote, DEFAULT_BRANCH]).trim()) {
    log(`no ${DEFAULT_BRANCH} branch — nothing captured yet`);
    return;
  }

  for (let attempt = 1; ; attempt += 1) {
    git(root, ['fetch', '--quiet', remote, DEFAULT_BRANCH]);
    const tip = git(root, ['rev-parse', 'FETCH_HEAD']).trim();
    const names = git(root, ['ls-tree', '--name-only', tip]).split('\n').filter(Boolean);
    const plan = planPrune({ names, retentionDays, now: new Date().toISOString() });
    const held = plan.holding.length
      ? `; holding ${plan.holding.length} aged capture(s) no extract run has marked processed`
      : '';

    if (plan.delete.length === 0) {
      log(`${plan.logCount} capture(s) on the branch, nothing deletable past ${retentionDays}d${held}`);
      return;
    }

    const captures = plan.delete.filter((p) => p.endsWith('.jsonl')).length;
    try {
      pushRemovals(root, {
        remote,
        tip,
        paths: plan.delete,
        message: `Claudinite: prune ${captures} processed conversation log(s) past ${retentionDays}d retention [skip ci]`,
      });
    } catch (e) {
      // Almost always a capture that landed mid-run: re-plan against the new tip.
      if (attempt >= PUSH_ATTEMPTS) throw e;
      log(`push rejected (attempt ${attempt}/${PUSH_ATTEMPTS}) — re-planning against the new tip`);
      continue;
    }
    log(`pruned ${captures} processed capture(s) past ${retentionDays}d, ${plan.delete.length} path(s) in total${held}`);
    return;
  }
}

// Run only when invoked directly (the scheduler's `node worker.mjs`), never on import.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(`logs-prune failed: ${e.message}`); process.exit(1); });
}
